def action_deltas_from(before, after):
    a, b = np.asarray(before), np.asarray(after)
    changed = np.argwhere(a != b)
    if len(changed) == 0:
        return 0, None
    return len(changed), (
        int(changed[:, 0].min()), int(changed[:, 1].min()),
        int(changed[:, 0].max()), int(changed[:, 1].max()),
    )


